 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;u uuid:=auth.uid();
a mission_factory_owner.quest_arcs;e mission_factory_owner.quest_episodes;ordinary boolean:=false;
BEGIN
SELECT * INTO e FROM mission_factory_owner.quest_episodes WHERE id=p_episode;
SELECT * INTO a FROM mission_factory_owner.quest_arcs WHERE id=e.arc_id;
ordinary:=a.availability_scope='public' AND a.execution_context='public_real'
 AND mission_public_owner.human_positive_qualification_v1(a.public_release_sha256,true) IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.locations l WHERE l.id=p_location AND l.is_active AND NOT l.is_test AND NOT coalesce(l.is_exam_room,false));
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_lineage IS NULL OR p_version IS NULL OR p_episode IS NULL
OR (CASE WHEN a.availability_scope='public' AND a.execution_context='public_real' THEN ordinary IS DISTINCT FROM true ELSE p_location IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid END)
THEN RAISE EXCEPTION 'C395_NORMAL_STAFF_HUMAN_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
IF public.master_v2_is_master(u) IS DISTINCT FROM true
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C395_HUMAN_PREPARE_DISABLED' USING ERRCODE='42501';END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
IF v.author_user IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
THEN RAISE EXCEPTION 'C395_HUMAN_VERSION_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
PERFORM mission_factory_owner.quest_operator_assert_v3(p_episode);
END $function$;

