CREATE OR REPLACE FUNCTION mission_factory_owner.c444_enrollment_open_v1(p_episode uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ep mission_factory_owner.quest_episodes; a mission_factory_owner.quest_arcs;
begin
 IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes oe JOIN mission_factory_owner.quest_arcs oa ON oa.id=oe.arc_id WHERE oe.id=p_episode AND oa.availability_scope='public' AND oa.source_document->>'content_kind'='quest_human') THEN RETURN mission_factory_owner.human_ordinary_enrollment_open_v1(p_episode);END IF;
IF (NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true) AND NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes oe WHERE oe.id=p_episode AND mission_factory_owner.human_ordinary_arc_scope_v1(oe.arc_id,true)) THEN RETURN false;END IF;

 select * into ep from mission_factory_owner.quest_episodes where id=p_episode;
 select * into a from mission_factory_owner.quest_arcs where id=ep.arc_id;
 if ep.id is null or ep.state<>'source_only' or exists(select 1 from mission_factory_owner.quest_run_sources where episode_id=p_episode) then return false;end if;
 if not mission_factory_owner.quest_public_open_v3(a.id) then return false;end if;
 if mission_factory_owner.quest_publication_scope_v3(a.id,true) not in('staff','public') then return false;end if;
 if ep.ordinal=1 then return a.state in('staff_source','public_source');end if;
 return a.quest_kind='trama' and a.state='in_progress' and exists(
   select 1 from mission_factory_owner.quest_episodes prev
   join mission_factory_owner.quest_run_sources q on q.episode_id=prev.id and q.state='terminal'
   join mission_factory_owner.quest_terminal_receipts tr on tr.id=q.terminal_receipt_id
   where prev.arc_id=a.id and prev.ordinal=ep.ordinal-1
     and mission_factory_owner.quest_terminal_confirmed_v1(q.session_id) is not null);
end $function$;

