CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_successor_scope_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources;
 b mission_factory_owner.c384_human_bindings;
 av mission_factory_owner.c384_authoring_versions;
 a mission_factory_owner.quest_arcs;
 ne mission_factory_owner.quest_episodes;
 term jsonb;why text;ready boolean:=false;
BEGIN
 IF p_session IS NULL THEN RAISE EXCEPTION 'C470_SESSION_REQUIRED' USING ERRCODE='22023';END IF;
 -- Master identity remains distinct from PG identity, including the same normal Auth account.
 PERFORM mission_factory_owner.c407_identity_v1(p_session);
 PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT b FROM mission_factory_owner.c384_human_bindings WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT av FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=b.lineage_id AND version=b.authoring_version FOR SHARE;
 SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=q.arc_id FOR SHARE;
 IF b.assigned_master IS DISTINCT FROM auth.uid() OR av.author_user IS DISTINCT FROM auth.uid()
 OR av.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(av.document)
 OR av.document_sha256 IS DISTINCT FROM b.binding_snapshot->>'authoring_sha256'
 OR b.binding_sha256 IS DISTINCT FROM mission_factory_owner.sha(b.binding_snapshot)
 OR b.episode_id IS DISTINCT FROM q.episode_id OR b.source_sha256 IS DISTINCT FROM q.source_sha256
 THEN RAISE EXCEPTION 'C470_IMMUTABLE_AUTHORING_IDENTITY_REQUIRED' USING ERRCODE='42501';END IF;
 IF q.state='terminal' THEN term:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);END IF;
 IF term IS NOT NULL AND a.quest_kind='trama' THEN
  SELECT * INTO ne FROM mission_factory_owner.quest_episodes WHERE arc_id=q.arc_id AND ordinal=q.episode_ordinal+1 FOR SHARE;
  IF ne.id IS NOT NULL AND (ne.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(ne.source_document)
   OR ne.member_character_ids IS DISTINCT FROM q.roster_character_ids) THEN
   RAISE EXCEPTION 'C470_SUCCESSOR_SOURCE_OR_IMMUTABLE_ROSTER_DRIFT' USING ERRCODE='40001';END IF;
 END IF;
 why:=CASE
  WHEN (NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true) AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL THEN 'DISABLED'
  WHEN q.state<>'terminal' THEN 'CURRENT_EPISODE_NOT_TERMINAL'
  WHEN term IS NULL THEN 'TERMINAL_PUBLICATION_NOT_CONFIRMED'
  WHEN ne.id IS NULL THEN 'NO_SUCCESSOR'
  WHEN NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
   OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled) THEN 'HUMAN_PREPARE_DISABLED'
  WHEN EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources WHERE episode_id=ne.id) THEN 'SUCCESSOR_ALREADY_PREPARED'
  WHEN mission_factory_owner.c444_enrollment_open_v1(ne.id) IS DISTINCT FROM true THEN 'NATIVE_ENROLLMENT_CLOSED'
  ELSE 'READY' END;
 ready:=why='READY';
 RETURN jsonb_build_object('schema_version','quest-human-successor-scope/1',
  'from_session_id',p_session,'quest_arc_id',q.arc_id,
  'next_episode_id',ne.id,'next_ordinal',ne.ordinal,
  'lineage_id',CASE WHEN ne.id IS NOT NULL THEN b.lineage_id ELSE NULL END,
