 THEN RAISE EXCEPTION 'C463_OPTIN_PREPARED_STAFF_CAS_REQUIRED' USING ERRCODE='40001';END IF;
 SELECT * INTO n FROM mission_generic_owner.regia_human_session_optins_v1 WHERE master_session_id=p_session FOR UPDATE;
 IF FOUND THEN RAISE EXCEPTION 'C463_NATIVE_OPTIN_ALREADY_RESERVED' USING ERRCODE='40001';END IF;
 INSERT INTO mission_generic_owner.regia_human_session_optins_v1(master_session_id,actor_user,request_key) VALUES(p_session,auth.uid(),p_request);
 receipt:=jsonb_build_object('schema_version','quest-human-regia-optin/1','native_session_id',p_session,'request_key',p_request,'status','reserved',
 'assigned_master',auth.uid(),'source_sha256',q.source_sha256,'prepare_request_key',q.prepare_request_key,'expected_control_version',p_expected_control_version,
 'roster_snapshot_sha256',q.roster_snapshot_sha256,'identity_sha256',mission_factory_owner.sha(identity));
 INSERT INTO mission_factory_owner.c463_optin_receipts(session_id,request_key,actor_user,expected_control_version,source_sha256,identity_sha256,request_sha256,receipt,receipt_sha256)
 VALUES(p_session,p_request,auth.uid(),p_expected_control_version,q.source_sha256,mission_factory_owner.sha(identity),fp,receipt,mission_factory_owner.sha(receipt));
 RETURN receipt;
END $function$;

