CREATE OR REPLACE FUNCTION mission_factory_owner.quest_publication_scope_v3(p_arc uuid, p_open boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_factory_owner.quest_arcs;pub mission_factory_owner.publications;
begin
 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc;
 select * into strict pub from mission_factory_owner.publications where request_key=a.publication_request;
 IF p_open IS DISTINCT FROM false OR pub.content_kind IS DISTINCT FROM 'quest_human' THEN
 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc for share;
 select * into strict pub from mission_factory_owner.publications where request_key=a.publication_request for share;
 END IF;
 IF pub.content_kind='quest_human' AND a.source_document->>'schema_version'='mission-factory-draft/3' THEN PERFORM mission_factory_owner.c416_arc_assert_v1(a.id,p_open);RETURN a.availability_scope;END IF;
 if pub.content_kind<>'quest_ai' or pub.quest_arc_id is distinct from a.id or pub.source_sha256 is distinct from a.source_sha256
 or a.source_sha256 is distinct from mission_factory_owner.sha(a.source_document) then raise exception 'MF_QUEST_PUBLICATION_SOURCE_DRIFT' using errcode='40001';end if;
 if a.availability_scope='staff' then
  if pub.target<>'staff' or pub.state<>'staff' then raise exception 'MF_QUEST_STAFF_SOURCE_DRIFT' using errcode='42501';end if;
 else
  if pub.target<>(case when a.execution_context='staff_simulation' then 'staff' else 'public' end) or pub.state not in('staff','scheduled','open') or (p_open and not mission_factory_owner.quest_public_open_v3(a.id))
  or pub.release_revision_sha256 is distinct from a.public_release_sha256
  then raise exception 'MF_QUEST_PUBLIC_SOURCE_UNAVAILABLE' using errcode='55000';end if;
  perform mission_factory_owner.quest_execution_assert_v4(a.id,p_open);
 end if;
 return a.availability_scope;
end $function$;

