CREATE OR REPLACE FUNCTION mission_factory_owner.quest_compile_check_v1(p_episode uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e mission_factory_owner.quest_episodes%rowtype;
  a mission_factory_owner.quest_arcs%rowtype;
  c mission_factory_owner.catalog_versions%rowtype;
  phase jsonb; option jsonb; cap jsonb; reg mission_factory_owner.quest_decision_registry%rowtype;
  errors jsonb:='[]'::jsonb; phases jsonb; i integer; j integer; k text; dest text;
  has_terminal boolean:=false; same_event integer; reachable boolean;
  opponent_count integer; combat_count integer; combat_map jsonb;
begin
  perform mission_factory_owner.quest_operator_assert_v3(p_episode);
  select * into strict e from mission_factory_owner.quest_episodes where id=p_episode;
  select * into strict a from mission_factory_owner.quest_arcs where id=e.arc_id;
  select * into strict c from mission_factory_owner.catalog_versions where active and qualified;
  phases:=e.source_document->'phases';
  if e.source_sha256<>mission_factory_owner.sha(e.source_document)
     or a.source_sha256<>mission_factory_owner.sha(a.source_document)
     or e.state<>'source_only' or a.state not in('staff_source','public_source','scheduled_source','in_progress')
     or c.version is null or c.document_sha256<>mission_factory_owner.sha(c.document)
     or jsonb_typeof(phases) is distinct from 'array'
     or jsonb_typeof(c.document->'capabilities') is distinct from 'array'
     or jsonb_typeof(a.source_document->'npc_bindings') is distinct from 'array'
     or jsonb_typeof(e.source_document->'maps') is distinct from 'array'
  then return jsonb_build_array(jsonb_build_object('code','QUEST_SOURCE_UNAVAILABLE',
    'path','quest.episodes','message','La puntata pubblicata non è pronta per la compilazione.')); end if;
  if jsonb_array_length(phases)=0 then
    return jsonb_build_array(jsonb_build_object('code','QUEST_SOURCE_UNAVAILABLE',
      'path','quest.episodes','message','La puntata deve contenere almeno una fase.'));
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('code',x.value->>'code',
    'path',x.value->>'path',
    'message','Controlla questo campo e scegli una risorsa disponibile.') order by x.ord),'[]'::jsonb)
  into errors
  from jsonb_array_elements(mission_factory_owner.quest_deep_validate_v2(
    a.draft_id,a.source_document)) with ordinality x(value,ord);
  if errors<>'[]'::jsonb then return errors; end if;
  for i in 0..jsonb_array_length(phases)-1 loop
    phase:=phases->i; k:=phase->>'step_key';
    perform mission_factory_owner.c360_native_phase_assert_v1(phase);
    if k is null or k !~ '^[a-z][a-z0-9_]{0,63}$'
       or (select count(*) from jsonb_array_elements(phases) x where x.value->>'step_key'=k)<>1
    then errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_STEP_INVALID',
      'path',format('quest.episodes[%s].phases[%s].step_key',e.ordinal-1,i),
      'message','Assegna a questa fase una chiave valida e unica.')); continue; end if;
    select x.value into cap from jsonb_array_elements(c.document->'capabilities') x
      where x.value->>'key'=phase->>'capability_key'
        and x.value->>'qualified'='true'
        and CASE WHEN a.availability_scope='public' AND a.source_document->>'content_kind'='quest_human' THEN mission_factory_owner.human_ordinary_arc_scope_v1(a.id,true) AND x.value->>'key' IN('narrative.scene','combat.encounter','d100.native','terminal.result') ELSE mission_factory_owner.c416_cap_allowed_v1(x.value,a.source_document->>'content_kind') END;
    if cap is null then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','QUEST_CAPABILITY_UNAVAILABLE',
      'path',format('quest.episodes[%s].phases[%s].capability_key',e.ordinal-1,i),
      'message','Questa capacità non è disponibile per una Quest IA. Scegline una fra quelle abilitate.'));
      continue; end if;
    if phase->>'capability_key'='combat.encounter' then
      select m.value into combat_map from jsonb_array_elements(e.source_document->'maps') m
        where m.value->>'step_key'=k;
      select count(*),count(*) filter(where b.value->>'team'='avversari')
        into combat_count,opponent_count
        from jsonb_array_elements(a.source_document->'npc_bindings') b
        where b.value->'phase_keys' ? (e.episode_key||'/'||k)
          and b.value->>'combat'='true';
      if jsonb_typeof(combat_map->'arena_ref') is distinct from 'object' then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_ARENA_UNAVAILABLE',
          'path',format('quest.episodes[%s].maps',e.ordinal-1),
          'message','Scegli un''arena di scontro disponibile per questa fase.'));
      end if;
      if combat_count not between 1 and (CASE WHEN a.source_document->>'content_kind'='quest_human' THEN 4 ELSE 12 END) or opponent_count<1 then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_COMBAT_ACTORS_MISSING',
          'path',format('quest.episodes[%s].phases[%s]',e.ordinal-1,i),
          'message','Per aprire uno scontro servono un avversario idoneo e la sua presenza in questa fase.'));
      end if;
      if exists(select 1 from mission_factory_owner.quest_decision_registry r
          where r.catalog_version=c.version and r.catalog_sha256=c.document_sha256
            and r.capability_key='combat.encounter' and r.qualified
            and r.step_kind<>'mechanical') then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_COMBAT_STEP_INVALID',
          'path',format('quest.episodes[%s].phases[%s].capability_key',e.ordinal-1,i),
          'message','Questa fase di scontro non è configurata correttamente.'));
      end if;
    end if;
    if length(btrim(coalesce(phase->>'public_setup','')))=0
       or length(btrim(coalesce(phase->>'public_setup','')))>500 then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_PUBLIC_SETUP_INVALID',
        'path',format('quest.episodes[%s].phases[%s].public_setup',e.ordinal-1,i),
        'message','Descrivi la fase in un testo da 1 a 500 caratteri.'));
    end if;
    if jsonb_typeof(phase->'transition_options') is distinct from 'array' then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_TRANSITION_INVALID',
        'path',format('quest.episodes[%s].phases[%s].transition_options',e.ordinal-1,i),
        'message','Aggiungi una condizione di passaggio valida.')); continue; end if;
    if jsonb_array_length(phase->'transition_options')=0 then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_TRANSITION_INVALID',
        'path',format('quest.episodes[%s].phases[%s].transition_options',e.ordinal-1,i),
        'message','Aggiungi una condizione di passaggio valida.')); continue; end if;
    if (select count(distinct r.step_kind)
        from jsonb_array_elements(phase->'transition_options') o
        join mission_factory_owner.quest_decision_registry r
          on r.catalog_version=c.version and r.catalog_sha256=c.document_sha256
         and r.capability_key=phase->>'capability_key'
         and r.decision_key=o.value->>'decision_key' and r.qualified)>1 then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_STEP_KIND_CONFLICT',
        'path',format('quest.episodes[%s].phases[%s].transition_options',e.ordinal-1,i),
        'message','Le condizioni di questa fase richiedono tipi di scena incompatibili.'));
    end if;
    for j in 0..jsonb_array_length(phase->'transition_options')-1 loop
      option:=phase->'transition_options'->j; dest:=option->>'to_step_key';
      if dest is null and coalesce(option->>'terminal_outcome','')
         not in ('success','failure') then
        errors:=errors||jsonb_build_array(jsonb_build_object(
          'code','QUEST_TERMINAL_OUTCOME_REQUIRED',
          'path',format('quest.episodes[%s].phases[%s].transition_options[%s].terminal_outcome',e.ordinal-1,i,j),
          'message','Scegli se questa conclusione prevista è riuscita o fallita.'));
      elsif dest is not null and option ? 'terminal_outcome' then
        errors:=errors||jsonb_build_array(jsonb_build_object(
          'code','QUEST_TERMINAL_OUTCOME_FORBIDDEN',
          'path',format('quest.episodes[%s].phases[%s].transition_options[%s].terminal_outcome',e.ordinal-1,i,j),
          'message','Rimuovi l’esito da un passaggio che prosegue verso un’altra fase.'));
      end if;
      select * into reg from mission_factory_owner.quest_decision_registry
        where catalog_version=c.version and catalog_sha256=c.document_sha256
          and capability_key=phase->>'capability_key'
          and decision_key=option->>'decision_key' and qualified;
      if reg.decision_key is null or not (cap->'decision_keys' ? (option->>'decision_key'))
         or not exists(select 1 from public.mission_evidence_capabilities mc
           where mc.capability_key=reg.evidence_capability_key and mc.enabled
             and mc.domain='quest' and mc.source_kind=reg.evidence_source_kind
             and mc.provider_owner=reg.provider_owner
             and mc.feature_version=reg.feature_version
             and mc.provider_contract_version=reg.provider_contract_version
             and mc.projection_version=reg.projection_version)
      then errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_DECISION_UNAVAILABLE',
        'path',format('quest.episodes[%s].phases[%s].transition_options[%s].decision_key',e.ordinal-1,i,j),
        'message','Questa condizione di passaggio non è disponibile per la fase. Scegli una condizione proposta.'));
        continue; end if;
      if dest is null then
        if not reg.terminal_route or reg.step_kind<>'narrative' or phase->>'capability_key'<>'terminal.result'
 OR NOT ((reg.trigger_source_kind='narrative_event' AND k=e.source_document#>>'{terminal_rules,terminal_step_key}')
 OR (reg.trigger_source_kind='quest_native_terminal' AND mission_factory_owner.c474_synthetic_source_v1(e.id,k,option->>'terminal_outcome'))) then
          errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_TERMINAL_INVALID',
            'path',format('quest.episodes[%s].phases[%s].transition_options[%s].to_step_key',e.ordinal-1,i,j),
            'message','Questa condizione deve indicare una fase di arrivo.'));
        else has_terminal:=true; end if;
      elsif reg.terminal_route or not exists(select 1 from jsonb_array_elements(phases) x
          where x.value->>'step_key'=dest) then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_DESTINATION_MISSING',
          'path',format('quest.episodes[%s].phases[%s].transition_options[%s].to_step_key',e.ordinal-1,i,j),
          'message','La fase di destinazione non esiste in questa puntata.'));
      end if;
    end loop;
    -- Without a certified one-of receipt, two routes for the same event can
    -- tie in the native resolver. Keep them unavailable in this version.
    select count(*) into same_event from (
      select r.event_kind,count(*) n
      from jsonb_array_elements(phase->'transition_options') o
      join mission_factory_owner.quest_decision_registry r
        on r.catalog_version=c.version and r.catalog_sha256=c.document_sha256
       and r.capability_key=phase->>'capability_key' and r.decision_key=o.value->>'decision_key'
       and r.qualified and not r.terminal_route
      group by r.event_kind having count(*)>1
    ) x;
    if same_event>0 then errors:=errors||jsonb_build_array(jsonb_build_object(
      'code','QUEST_TRANSITION_AMBIGUOUS',
      'path',format('quest.episodes[%s].phases[%s].transition_options',e.ordinal-1,i),
      'message','Due passaggi possono attivarsi insieme. Scegli condizioni distinte.'));
    end if;
  end loop;
  if not has_terminal then errors:=errors||jsonb_build_array(jsonb_build_object(
    'code','QUEST_TERMINAL_UNREACHABLE',
    'path',format('quest.episodes[%s].phases',e.ordinal-1),
    'message','La puntata deve poter arrivare a una conclusione.')); end if;
  if has_terminal and errors='[]'::jsonb then
    with recursive walk(step_key,path) as (
      select phases->0->>'step_key',array[phases->0->>'step_key']::text[]
      union all
      select o.value->>'to_step_key',w.path||(o.value->>'to_step_key')
      from walk w
      join lateral jsonb_array_elements(phases) ph on ph.value->>'step_key'=w.step_key
      cross join lateral jsonb_array_elements(ph.value->'transition_options') o
      where o.value->>'to_step_key' is not null
        and not ((o.value->>'to_step_key')=any(w.path))
    )
    select exists(select 1 from walk
      where step_key=e.source_document#>>'{terminal_rules,terminal_step_key}') into reachable;
    if not coalesce(reachable,false) then
      errors:=errors||jsonb_build_array(jsonb_build_object(
        'code','QUEST_TERMINAL_UNREACHABLE',
        'path',format('quest.episodes[%s].phases',e.ordinal-1),
        'message','La puntata deve poter arrivare a una conclusione.'));
    end if;
  end if;
  if exists(select 1 from jsonb_array_elements(phases) ph
     cross join lateral jsonb_array_elements(ph->'transition_options') opt
     join mission_factory_owner.quest_decision_registry registry_spatial on registry_spatial.catalog_version=c.version
       and registry_spatial.catalog_sha256=c.document_sha256 and registry_spatial.capability_key=ph->>'capability_key'
       and registry_spatial.decision_key=opt->>'decision_key' and registry_spatial.trigger_source_kind='spatial_event') then
    errors:=errors||jsonb_build_array(jsonb_build_object('code','QUEST_SPATIAL_NATIVE_ADAPTER_UNQUALIFIED',
      'path','quest.episodes','message','La ricevuta spaziale nativa deve essere riconciliata prima di qualificare questa capacità.'));
  end if;
  return errors;
end $function$;

