CREATE OR REPLACE FUNCTION mission_factory_owner.quest_compile_v1(p_episode uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e mission_factory_owner.quest_episodes%rowtype;
  a mission_factory_owner.quest_arcs%rowtype;
  c mission_factory_owner.catalog_versions%rowtype;
  p public.mission_plans%rowtype;
  v public.mission_plan_versions%rowtype;
  reg mission_factory_owner.quest_decision_registry%rowtype;
  errors jsonb; phases jsonb; phase jsonb; option jsonb; scenes jsonb:='[]'::jsonb;
  scene jsonb; actors jsonb; map_ref jsonb; terminal_options jsonb;
  triggers jsonb; encounters jsonb; encounter_actors jsonb;
  i integer; j integer; tkey text; plan_id uuid; version_id uuid;
  plan_sha text; definition jsonb; definition_sha text;
begin
  perform mission_factory_owner.quest_operator_assert_v3(p_episode);
  if p_episode is null then raise exception 'MF_QUEST_COMPILE_INPUT' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_episode::text,25092512));
  errors:=mission_factory_owner.quest_compile_check_v1(p_episode);
  if errors<>'[]'::jsonb then return jsonb_build_object('state','blocked','errors',errors); end if;
  select * into strict e from mission_factory_owner.quest_episodes where id=p_episode for update;
  select * into strict a from mission_factory_owner.quest_arcs where id=e.arc_id for share;
  IF a.availability_scope='public' AND a.source_document->>'content_kind'='quest_human' THEN PERFORM mission_factory_owner.human_ordinary_arc_scope_v1(a.id,false);PERFORM mission_factory_owner.human_ordinary_npc_bundle_assert_v1(a.draft_id);END IF;
  select * into strict c from mission_factory_owner.catalog_versions where active and qualified for share;
  select * into p from public.mission_plans
    where source_kind='quest' and quest_episode_id=e.id and stato='attivo' for share;
  if found then
    select * into strict v from public.mission_plan_versions
      where plan_id=p.id and stato='approvata' order by versione desc limit 1 for share;
    if p.quest_source_sha256<>e.source_sha256
       or not exists(select 1 from mission_generic_owner.definitions d
         where d.plan_version_id=v.id and d.plan_sha256=v.plan_sha256
           and d.definition->>'schema_version'='mission-factory-quest-definition/1'
           and d.definition->>'quest_episode_id'=e.id::text
           and d.definition->>'source_sha256'=e.source_sha256)
    then raise exception 'MF_QUEST_COMPILE_REPLAY_CONFLICT' using errcode='40001'; end if;
    return jsonb_build_object('state','compiled','plan_id',p.id,
      'plan_version_id',v.id,'plan_sha256',v.plan_sha256,'source_sha256',e.source_sha256);
  end if;
  if not exists(select 1 from mission_factory_owner.drafts d
       where d.id=a.draft_id and d.control_version=a.draft_version
         and d.state='published' and d.document is not distinct from a.source_document
         and d.document_sha256=mission_factory_owner.sha(d.document)) then
    raise exception 'MF_QUEST_COMPILE_DRAFT_DRIFT' using errcode='40001'; end if;
  phases:=e.source_document->'phases';
  plan_id:=extensions.uuid_generate_v5(e.id,'mission-factory:quest-plan/1');
  version_id:=extensions.uuid_generate_v5(e.id,'mission-factory:quest-plan-version/1:'||e.source_sha256||':'||c.document_sha256);
