PERFORM mission_factory_owner.c384_human_identity_v1(p_session);
PERFORM mission_factory_owner.c395_revision_assert_v1(p_session);
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
SELECT array_agg(c.user_id ORDER BY c.id) INTO users FROM unnest(q.roster_character_ids)x(id) JOIN public.characters c ON c.id=x.id;
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR m.master_user IS DISTINCT FROM auth.uid()
