OR m.location_id IS DISTINCT FROM q.location_id
OR cardinality(q.roster_character_ids) NOT BETWEEN 1 AND 4 OR cardinality(users) IS DISTINCT FROM cardinality(q.roster_character_ids)
OR ((q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation' OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)
 AND (mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL OR (q.execution_context='staff_simulation' AND combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)))
THEN RAISE EXCEPTION 'C407_IMMUTABLE_NORMAL_STAFF_HUMAN_SCOPE' USING ERRCODE='42501';END IF;
END $function$;

